def read_mesh(path):
    """读三角网格；失败返回 None（绝不抛异常）。"""
    try:
        mesh = o3d.io.read_triangle_mesh(path)
        if mesh is not None and not mesh.is_empty():
            return mesh
    except Exception:            # 非 UTF-8 路径 / ASSIMP 失败
        pass
    if has_non_ascii(path):      # 中文路径兜底：ASCII 副本重读
        alt = ascii_copy(path)   # 连 mtl 与贴图一起搬，引用名不合法时改写
        if alt:
            return o3d.io.read_triangle_mesh(alt)
    return None
